using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class R13Sample{public float time,distance,remaining,spin;public Vector3 position,velocity;public int breaks,impacts,bounces;public string surface;}
 [Serializable]public class R13Target{public string id;public List<Bounds> bounds=new List<Bounds>();}
 [Serializable]public class R13Trial{public string id,launch,final,contactTrace;public List<R13Sample> samples=new List<R13Sample>();public List<R13Target> targets=new List<R13Target>();public List<BreakRecord> breaks=new List<BreakRecord>();public List<string> impacts=new List<string>();}
 [Serializable]public class R13Report{public string state="RUNNING",revision="r13-contact-probe1",method="Natural initialization, fixed601 active charge ticks and manual Tick(1/60); saved r12 input conditions; only two stopping windows observed. No teleport, new force or altered physics coefficients.";public List<R13Trial> trials=new List<R13Trial>();}
 R13Sample R13Point(object sim){var b=(Rigidbody)Property(sim,"Body");return new R13Sample{time=F(sim,"Time"),distance=F(sim,"Distance"),remaining=Convert.ToSingle(Property(sim,"RotorRemaining")),spin=Convert.ToSingle(Property(sim,"SpinRps")),position=b.position,velocity=b.linearVelocity,breaks=Convert.ToInt32(Property(sim,"DestructionBoostCount")),impacts=Convert.ToInt32(Field(sim,"ImpactID")),bounces=Convert.ToInt32(Property(sim,"OverdriveGroundBounces")),surface=(string)Field(sim,"LastSurface")};}
 void R13Collect(R13Trial row,object sim){foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});foreach(var e in (IEnumerable)Field(sim,"Impacts"))row.impacts.Add(JsonUtility.ToJson(e));row.contactTrace=(string)Call(sim,"ReviewContactTraceJson");}
 [UnityTest]public IEnumerator R13ContactProbe(){var referenceField=cityType.GetField("routeR12",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);string referencePath=Environment.GetEnvironmentVariable("CRAB_REFERENCE_LAYOUT");Assert.That(File.Exists(referencePath),Is.True,"Set CRAB_REFERENCE_LAYOUT to the saved1209c4f Placements.json");referenceField.SetValue(null,JsonUtility.FromJson(File.ReadAllText(referencePath),referenceField.FieldType));Directory.CreateDirectory(Evidence);var report=new R13Report();string file=Path.Combine(Evidence,"contact-route.json");Assert.That(File.Exists(file),Is.False);Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();
 foreach(var spec in new[]{new R12Spec{id="r12-standard-stop-probe",angle=12,level=0,rate=2},new R12Spec{id="r12-left-stop-probe",angle=35,direction=-1}}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var row=new R13Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);float start=spec.direction==1?980:1475,end=spec.direction==1?1180:1700,next=0;foreach(var panel in (IEnumerable)Field(sim,"panels")){var pos=(Vector3)Field(panel,"position");if(Mathf.Abs(pos.x)<start||Mathf.Abs(pos.x)>end||Mathf.Sign(pos.x)!=spec.direction)continue;var target=new R13Target{id=(string)Field(panel,"id")};foreach(var shape in (IEnumerable)Field(panel,"shapes"))target.bounds.Add(((Collider)shape).bounds);row.targets.Add(target);}bool captured=false;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){Call(current,"Tick",1f/60);var point=R13Point(sim);if(point.distance>=start&&point.time>=next){row.samples.Add(point);next=point.time+.125f;}if(!captured&&point.distance>(spec.direction==1?1080:1603)){CaptureRoute(spec.id,"window");captured=true;}}
 row.samples.Add(R13Point(sim));row.final=JsonUtility.ToJson(State(current));R13Collect(row,sim);CaptureRoute(spec.id,"stop");save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();referenceField.SetValue(null,null);}

 [UnityTest]public IEnumerator R13RouteCompare(){Directory.CreateDirectory(Evidence);string scope=Environment.GetEnvironmentVariable("CRAB_EVIDENCE_SCOPE");var report=new R13Report{revision="r13-route-"+scope};string file=Path.Combine(Evidence,"contact-route.json");Assert.That(File.Exists(file),Is.False);Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();
 var specs=scope=="compare03"?new[]{new R12Spec{id="step3-left35-offset-relay",angle=35,direction=-1}}:scope=="compare01"?new[]{new R12Spec{id="step1-standard12",angle=12,level=0,rate=2},new R12Spec{id="step1-right35-boundary",angle=35}}:new[]{new R12Spec{id="step2-left35",angle=35,direction=-1},new R12Spec{id="step2-left45-angle-neighbor",angle=45,direction=-1}};
 foreach(var spec in specs){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var row=new R13Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);float start=spec.direction==1?1030:1500,next=0;bool before=false,hit=false,after=false;int afterTick=-1;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){Call(current,"Tick",1f/60);var point=R13Point(sim);if(point.distance>=start&&point.time>=next){row.samples.Add(point);next=point.time+.125f;}if(!before&&point.distance>(spec.direction==1?1065:1560)){CaptureRoute(spec.id,"approach");before=true;}if(!hit){foreach(var e in (IEnumerable)Field(sim,"BreakEvents")){string id=(string)Field(e,"id");if(id.StartsWith(spec.direction==1?"far-r10-+1-05-":"r11-country--1-1-",StringComparison.Ordinal)){CaptureRoute(spec.id,"group-first-break");hit=true;afterTick=tick+12;break;}}}if(hit&&!after&&tick>=afterTick){CaptureRoute(spec.id,"group-follow-through");after=true;}}
 row.samples.Add(R13Point(sim));row.final=JsonUtility.ToJson(State(current));R13Collect(row,sim);CaptureRoute(spec.id,"result");save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}

 [UnityTest]public IEnumerator R13FinalVisual(){Directory.CreateDirectory(Evidence);yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(35,3,6,-1);var sim=Property(current,"ReviewSimulation");var report=new R13Report{revision="r13-country-relay2-final-visual"};var row=new R13Trial{id="final-left35",launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);bool ground=false,tank=false,arch=false,afterArch=false;int archAfter=-1;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){
 Call(current,"Tick",1f/60);var point=R13Point(sim);
 if(!ground&&point.distance>1560){var grounds=current.GetComponentsInChildren<Transform>(true).Where(x=>x.name=="route ground").ToArray();Assert.That(grounds.Length,Is.EqualTo(2));foreach(var g in grounds){g.localPosition=new Vector3(Mathf.Sign(g.localPosition.x)*2450,-.2f,110);g.localScale=new Vector3(1700,.3f,230);}CaptureRoute("r13-ground-before","same-pose");foreach(var g in grounds){g.localPosition=new Vector3(Mathf.Sign(g.localPosition.x)*2300,-.2f,110);g.localScale=new Vector3(2000,.3f,230);}CaptureRoute("r13-ground-after","same-pose");ground=true;}
 foreach(var e in (IEnumerable)Field(sim,"BreakEvents")){string id=(string)Field(e,"id");if(!tank&&id=="r11-country--1-1-0-hvac_unit"){CaptureRoute("r13-final","tank-hit");tank=true;}if(!arch&&id=="r11-launchrange--1-0-0-port_lattice_loader_r10"){CaptureRoute("r13-final","arch-hit");arch=true;archAfter=tick+6;}}
 if(arch&&!afterArch&&tick>=archAfter){CaptureRoute("r13-final","arch-secondary-follow");afterArch=true;}
 }
 Assert.That(ground&&tank&&arch&&afterArch,Is.True);row.final=JsonUtility.ToJson(State(current));R13Collect(row,sim);CaptureRoute("r13-final","result");Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Call(current,"RetryLaunch","");Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(State(current),"destructionEvent")),Is.EqualTo(0));Assert.That(F(State(current),"hitStopRemaining"),Is.EqualTo(0));CaptureRoute("r13-final","retry");report.state="COMPLETED";File.WriteAllText(Path.Combine(Evidence,"final-visual.json"),JsonUtility.ToJson(report,true));Call(current,"ShutdownReviewPhysics");current=null;yield return null;
 }
}
